Method.Source:
[DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@NDX:NXAPrintRefereces"))]
public boolean parmPrintReferences(boolean _printRef = printReferences)
{
    printReferences = _printRef;
    return printReferences;
}

[DataMemberAttribute('ProdId')]
